look.customCSS:
/* ───── 漫画对白 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScxMicgaGVpZ2h0PScxMicgdmlld0JveD0nMCAwIDEyIDEyJz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4xJyBmaWxsPScjRTJFMkRDJy8+PGNpcmNsZSBjeD0nOScgY3k9JzknIHI9JzEuMScgZmlsbD0nI0UyRTJEQycvPjwvc3ZnPg==") 0 0/12px 12px,#FAFAF7 !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：白底一道粗黑线，名字像漫画标题框 */
[data-wk="chathead"]{background:#FFFFFF !important;border-bottom:2px solid #1A1A1A !important;box-shadow:0 3px 0 #1A1A1A !important}
[data-wk="headink"],[data-wk="headink"] *{color:#1A1A1A !important;font-weight:800 !important}
[data-wk="headdim"]{color:#8A8A85 !important}
[data-wk="chatback"] svg{stroke:#1A1A1A !important;stroke-width:2.6 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img{border-radius:50% !important;box-shadow:0 0 0 2px #1A1A1A,2px 2px 0 2px #1A1A1A !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:32px !important;min-width:32px !important;height:32px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/28px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆，粗黑边＋错位影 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 2px #1A1A1A,3px 3px 0 2px #1A1A1A !important}

/* 名字：他头上一块黑底白字名牌；我不写名字 */
[data-wk="name"][data-me="1"]{display:none !important}
[data-wk="name"][data-me="0"]{display:inline-block !important;background:#1A1A1A !important;color:#fff !important;font-size:11px !important;letter-spacing:.15em !important;padding:2px 12px !important;margin:0 0 -2px 16px !important;border-radius:0 !important;position:relative !important;z-index:2 !important}
[data-wk="msg"][data-first="0"] [data-wk="name"]{display:none !important}

/* 对白框：粗黑描边＋实心错位黑影 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border:2px solid #1A1A1A !important;border-radius:22px !important;box-shadow:4px 4px 0 #1A1A1A !important;color:#1A1A1A !important;font-weight:600 !important;padding:12px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#FBE27A !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFFFFF !important}
/* 尖角：我的从右下戳出去，他的从左边指向头像（只在一串第一条） */
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:-18px !important;left:auto !important;bottom:2px !important;top:auto !important;width:22px !important;height:18px !important;background:url("data:image/svg+xml;base64,") left center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;left:-20px !important;right:auto !important;top:12px !important;bottom:auto !important;width:22px !important;height:18px !important;background:url("data:image/svg+xml;base64,") right center/contain no-repeat !important;border:none !important;transform:none !important}
/* 速度线：我那串第一条左边三道；他那串第一条右上两颗闪光星 */
[data-wk="bubble"][data-kind="text"]::before{content:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;left:-34px !important;right:auto !important;top:50% !important;width:26px !important;height:34px !important;margin-top:-17px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCA0MCc+PHBhdGggZD0nTTI4IDggTDYgMiBNMjggMjAgSDIgTTI4IDMyIEw2IDM4JyBzdHJva2U9JyMxQTFBMUEnIHN0cm9rZS13aWR0aD0nMi40JyBzdHJva2UtbGluZWNhcD0ncm91bmQnLz48L3N2Zz4=") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;right:-34px !important;left:auto !important;top:-18px !important;width:36px !important;height:30px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important}

/* 时间、已读：白底黑框小方签 */
[data-wk="time"] > span{display:inline-block !important;background:#FFFFFF !important;border:2px solid #1A1A1A !important;border-radius:0 !important;color:#1A1A1A !important;font-weight:700 !important;padding:1px 10px !important;font-size:11px !important;box-shadow:2px 2px 0 #1A1A1A !important}
[data-wk="meta"]{display:inline-block !important;background:#FFFFFF !important;border:1.6px solid #1A1A1A !important;color:#1A1A1A !important;padding:0 6px !important;font-size:10.5px !important;margin-top:8px !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#1A1A1A !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFFFF !important;border:2px solid #1A1A1A !important;border-radius:22px !important;box-shadow:4px 4px 0 #1A1A1A !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#1A1A1A !important}
/* 动描：旁白框——方角、浅灰、斜体，像漫画格子里的说明框 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{display:inline-block !important;background:#F1F0EA !important;border:1.6px solid #1A1A1A !important;border-radius:0 !important;box-shadow:none !important;color:#1A1A1A !important;font-style:italic !important;font-size:13px !important;padding:4px 12px !important}
/* 系统提示：不带框的一行小字，前后一颗小星 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#8A8A85 !important;font-size:11.5px !important;font-style:normal !important}
[data-wk="sysnotetext"]::before{content:"✦ " !important;color:#1A1A1A !important}

/* 底栏：白底一道粗黑线；左发送右回复（回复是一块斜着的黑色漫画框） */
[data-wk="composer"]{background:#FFFFFF !important;border-top:2px solid #1A1A1A !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#FFFFFF !important;border:2px solid #1A1A1A !important;border-radius:18px !important;box-shadow:3px 3px 0 #1A1A1A !important;color:#1A1A1A !important}
[data-wk="chatinput"]::placeholder{color:#8A8A85 !important}
[data-wk="chatplus"],[data-wk="send"]{width:32px !important;min-width:32px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/28px no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/28px no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:58px !important;min-width:58px !important;height:34px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(3px 3px 0 #FBE27A) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="msg"][data-me="1"] [data-wk="name"]{display:none !important}


/* ── 跟别的黑白粗边款分开：头像改方格子、错位黑影只留给对白框、顶栏做成分镜格、黄色当标志色 ── */
/* 头像：方形漫画格，细黑线框，不要粗圈和错位影 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img{border-radius:2px !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img{box-shadow:0 0 0 1.4px #1A1A1A,0 0 0 4px #FFFFFF,0 0 0 5.2px #1A1A1A !important}
/* 时间、已读：去掉错位影；时间是网点小格，已读是黄色小爆炸框 */
[data-wk="time"] > span{box-shadow:none !important;border:1.4px solid #1A1A1A !important;background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#FFFFFF !important}
[data-wk="meta"]{border:none !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;padding:3px 12px !important;font-weight:800 !important}
[data-wk="chatinput"]{box-shadow:none !important;border-radius:4px !important}
/* 顶栏：一条分镜格——左上角斜贴「EP.」，名字下面一道黄色马克笔，底边是网点 */
[data-wk="chathead"]{background:#FFFFFF !important;border-bottom:none !important;box-shadow:none !important;position:relative !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:-8px !important;height:8px !important;background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#FFFFFF !important;border-top:2px solid #1A1A1A !important;border-bottom:1px solid #1A1A1A !important;pointer-events:none !important;z-index:5 !important}
[data-wk="chathead"] [data-wk="headname"] > [data-wk="headink"]{background:linear-gradient(transparent 55%,#FBE27A 55%,#FBE27A 92%,transparent 92%) !important;padding:0 4px !important;position:relative !important;overflow:visible !important}
[data-wk="chathead"] [data-wk="headname"] > [data-wk="headink"]::before{content:"EP." !important;position:absolute !important;left:-6px !important;top:-14px !important;background:#1A1A1A !important;color:#FBE27A !important;font:800 9px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.1em !important;padding:2px 5px !important;transform:rotate(-8deg) !important}
[data-wk="body"]{padding-top:10px !important}
/* 底栏：顶边也是一条网点 */
[data-wk="composer"]{border-top:none !important;position:relative !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:-8px !important;height:8px !important;background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#FFFFFF !important;border-top:1px solid #1A1A1A !important;border-bottom:2px solid #1A1A1A !important;pointer-events:none !important}
/* 加号不再带错位格 */

[data-wk="chathead"] [data-wk="headname"]{overflow:visible !important}
[data-wk="chathead"] [data-wk="headname"] > [data-wk="headink"]::before{top:-12px !important;left:-2px !important;z-index:3 !important}

[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::after{right:-16px !important;bottom:8px !important;width:22px !important;height:17px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(4px 4px 0 #1A1A1A) !important;z-index:1 !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after{left:-23px !important;top:10px !important;width:29px !important;height:22px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:1 !important}


/* ───── 漫画对白 · 第二批：卡片（形状不动；对白框同款粗黑边＋错位影；小巧思：卡角一块黑底黄字的分镜标签） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:#FFFFFF !important;border:2px solid #1A1A1A !important;border-radius:4px !important;box-shadow:4px 4px 0 #1A1A1A !important;color:#1A1A1A !important;position:relative !important;overflow:visible !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#1A1A1A !important;border-color:#1A1A1A !important}
[data-wk="transfercard"]::before,[data-wk="namecard"]::before,[data-part="offlog"]::before{position:absolute !important;left:-6px !important;top:-12px !important;background:#1A1A1A !important;color:#FBE27A !important;font:800 10px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.12em !important;padding:4px 8px !important;transform:rotate(-4deg) !important;z-index:2 !important}
[data-wk="transfercard"]::before{content:"¥ 转账" !important}
[data-wk="namecard"]::before{content:"CAST · 名片" !important}
[data-part="offlog"]::before{content:"番外 · 线下" !important}
[data-wk="transfercard"],[data-wk="namecard"],[data-part="offlog"]{margin-top:14px !important}
/* 转账：金额下面一道黄色马克笔；收下盖黄色爆炸「GET!」，退回盖斜线网点 */
[data-wk="transferamount"]{background:linear-gradient(transparent 60%,#FBE27A 60%,#FBE27A 92%,transparent 92%) !important;font-weight:900 !important}
[data-wk="transferrule"]{border:none !important;height:2px !important;background:#1A1A1A !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#FFFFFF !important;border-top:2px solid #1A1A1A !important}
[data-wk="transferbtn"]{border-radius:2px !important;border:2px solid #1A1A1A !important;box-shadow:2px 2px 0 #1A1A1A !important}
[data-wk="transferbtn"][data-part="take"]{background:#FBE27A !important;color:#1A1A1A !important}
[data-wk="transferbtn"][data-part="back"]{background:#FFFFFF !important;color:#1A1A1A !important}
[data-wk="transferseal"]{border:2px solid #1A1A1A !important;border-radius:2px !important;background:#FFFFFF !important;color:#1A1A1A !important;box-shadow:none !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{width:66px !important;height:40px !important;border:none !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;transform:rotate(-10deg) !important;font-size:0 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]::after{content:"GET!" !important;font:900 13px/40px ui-monospace,Menlo,monospace !important;color:#1A1A1A !important;display:block !important;text-align:center !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"] *{display:none !important}
[data-wk="transfercard"][data-status="returned"]{background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#FFFFFF !important;opacity:.75 !important}
/* 红包：留红，加粗黑边错位影 */
[data-wk="rpcard"]{border:2px solid #1A1A1A !important;border-radius:4px !important;box-shadow:4px 4px 0 #1A1A1A !important}
[data-wk="rpenvelope"]{border:3px solid #1A1A1A !important;border-radius:6px !important;box-shadow:6px 6px 0 #1A1A1A !important}
/* 照片：漫画格子，下面一行等宽小字 */
[data-wk="photocard"]{padding:6px 6px 10px !important}
[data-wk="photoface"]{border-radius:0 !important;border:2px solid #1A1A1A !important;background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#F1F0EA !important}
[data-wk="photoface"] *,[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#1A1A1A !important}
/* 语音：小对白框，我黄他白 */
[data-wk="voice"][data-me]{background:#FFFFFF !important;border:2px solid #1A1A1A !important;border-radius:18px !important;box-shadow:3px 3px 0 #1A1A1A !important}
[data-wk="voice"][data-me="1"]{background:#FBE27A !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#1A1A1A !important}
[data-wk="voicewave"] span{background:#1A1A1A !important;border-radius:0 !important}
[data-wk="wxcardsky"]{background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#F1F0EA !important}
[data-wk="wxcardsky"] *{color:#1A1A1A !important}
[data-wk="wxcardsky"] svg{stroke:#1A1A1A !important}
[data-wk="wxcardsay"]{background:#FFFFFF !important;color:#1A1A1A !important;border-top:2px solid #1A1A1A !important}
[data-wk="geopin"]{background:#FBE27A !important;border:2px solid #1A1A1A !important;box-shadow:2px 2px 0 #1A1A1A !important}
[data-wk="geopinstem"]{background:#1A1A1A !important}
[data-wk="namecard"] img{border-radius:2px !important;box-shadow:0 0 0 1.4px #1A1A1A !important}
/* 拍一拍、通话结束：小爆炸框 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;border-radius:0 !important;color:#1A1A1A !important;font-weight:800 !important;padding:5px 18px !important;font-size:12px !important}
[data-wk="note"][data-part="call"] svg{stroke:#1A1A1A !important}
[data-wk="note"][data-part="callsum"]{color:#8A8A85 !important}
/* 线下小结 */
[data-wk="offlogtitle"]{font-weight:900 !important;letter-spacing:.1em !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#1A1A1A !important;text-decoration:underline !important;text-decoration-color:#FBE27A !important;text-decoration-thickness:4px !important;text-underline-offset:-1px !important}
[data-wk="offlogtranscript"]{border-top:2px solid #1A1A1A !important}
/* 加号面板：一格格漫画格子，黄白交替 */
[data-wk="chatpanel"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScxMicgaGVpZ2h0PScxMicgdmlld0JveD0nMCAwIDEyIDEyJz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4xJyBmaWxsPScjRTJFMkRDJy8+PGNpcmNsZSBjeD0nOScgY3k9JzknIHI9JzEuMScgZmlsbD0nI0UyRTJEQycvPjwvc3ZnPg==") 0 0/12px 12px,#FAFAF7 !important;border-top:2px solid #1A1A1A !important}
[data-wk="chattoolicon"]{background:#FFFFFF !important;border:2px solid #1A1A1A !important;border-radius:4px !important;box-shadow:3px 3px 0 #1A1A1A !important}
[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolicon"]{background:#FBE27A !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#1A1A1A !important;color:#1A1A1A !important}
[data-wk="chattoollabel"]{color:#1A1A1A !important;font-weight:700 !important}
/* 引用三处 */
[data-wk="quotedraft"]{background:#FFFFFF !important;border-top:none !important}
[data-wk="quote"]{background:repeating-linear-gradient(135deg,rgba(26,26,26,.16) 0 1.2px,transparent 1.2px 5px),#FFFFFF !important;color:#1A1A1A !important;border:1.6px solid #1A1A1A !important;border-left:5px solid #1A1A1A !important;border-radius:0 !important;opacity:1 !important}
[data-wk="quote"][data-me="1"]{background:#FBE27A !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#1A1A1A !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:3px solid #1A1A1A !important;padding-left:8px !important;opacity:.7 !important}
